const originals=new WeakMap();
const rawSelector='.bm-evidence-summary>span:nth-child(-n+2) strong,.bm-business-evidence td:nth-child(2),[data-i18n-preserve],.auth-account-actions>span,.bm-order-name,.bm-focus-order,.bm-focus-order+small,.bm-orders-table td:first-child,.bm-orders-table td:nth-child(2),.dd-order-info>div:nth-child(-n+2) strong,.source-detail span,#bm-customer option:not([value=""]),#dd-order option,#dd-revision option,#imported-order option,#imported-revision option';
let observer,languageScheduled=false;
function scheduleProjectLanguage(){if(languageScheduled)return;languageScheduled=true;requestAnimationFrame(()=>{languageScheduled=false;applyProjectLanguage();});}
export function applyProjectLanguage(){
 if(typeof document==='undefined'||document.body.classList.contains('auth-page'))return;
 observer?.disconnect();
 try{
 const locale=language();document.documentElement.lang=locale==='en'?'en':'zh-CN';document.body.dataset.projectLanguage=locale;
 const walker=document.createTreeWalker(document.documentElement,NodeFilter.SHOW_TEXT);let node;
 while((node=walker.nextNode())){
  const parent=node.parentElement;if(!parent||parent.closest('script,style,textarea,.auth-language,.project-language'))continue;
  if(parent.closest(rawSelector))continue;
  let state=originals.get(node);if(!state||node.data!==state.applied)state={source:node.data,applied:node.data};
  const raw=!!parent.closest('td')&&!parent.closest('[data-i18n-label]');const translated=translateText(state.source,locale,!raw);if(translated!==node.data)node.data=translated;state.applied=translated;originals.set(node,state);
 }
 for(const el of document.querySelectorAll('[placeholder],[aria-label],[title],[data-tip]')){
  if(el.closest('.auth-language,.project-language')||el.closest(rawSelector))continue;
  let state=originals.get(el);if(!state)state={};
  for(const attr of ['placeholder','aria-label','title','data-tip']){if(!el.hasAttribute(attr))continue;const current=el.getAttribute(attr);if(!state[attr]||current!==state[attr].applied)state[attr]={source:current,applied:current};const translated=translateText(state[attr].source,locale);if(current!==translated)el.setAttribute(attr,translated);state[attr].applied=translated;}
  originals.set(el,state);
 }
 document.querySelectorAll('[data-project-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.projectLang===locale);b.setAttribute('aria-pressed',String(b.dataset.projectLang===locale));});
 }finally{observer?.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title','data-tip']});}
}
export function installProjectLanguage(){
 observer=new MutationObserver(scheduleProjectLanguage);
 observer.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title','data-tip']});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-project-lang]');if(!b)return;try{localStorage.setItem('qiying-auth-language',b.dataset.projectLang);}catch{}applyProjectLanguage();});
 window.addEventListener('storage',e=>{if(e.key==='qiying-auth-language')applyProjectLanguage();});
}
export function languageControl(){return '<div class="project-language" role="group" aria-label="Language / 语言"><button type="button" data-project-lang="zh">中文</button><button type="button" data-project-lang="en">EN</button></div>';}
